SELECT jsonb_object_agg(c.relname,jsonb_build_object(
 'columns',(SELECT jsonb_object_agg(a.attname,jsonb_build_object('type',format_type(a.atttypid,a.atttypmod),'nn',a.attnotnull)) FROM pg_attribute a WHERE a.attrelid=c.oid AND a.attnum>0 AND NOT a.attisdropped),
 'pk',COALESCE((SELECT jsonb_agg(a.attname ORDER BY u.ordinality) FROM pg_constraint k CROSS JOIN LATERAL unnest(k.conkey) WITH ORDINALITY u(attnum,ordinality) JOIN pg_attribute a ON a.attrelid=k.conrelid AND a.attnum=u.attnum WHERE k.conrelid=c.oid AND k.contype='p'),'[]'::jsonb),
 'unique',COALESCE((SELECT jsonb_object_agg(i.indexrelid::regclass::text,(SELECT jsonb_agg(a.attname ORDER BY u.ordinality) FROM unnest(i.indkey::smallint[]) WITH ORDINALITY u(attnum,ordinality) JOIN pg_attribute a ON a.attrelid=i.indrelid AND a.attnum=u.attnum WHERE u.ordinality<=i.indnkeyatts)) FROM pg_index i WHERE i.indrelid=c.oid AND i.indisunique AND i.indpred IS NULL AND i.indexprs IS NULL),'{}'::jsonb),
 'fks',COALESCE((SELECT jsonb_object_agg(k.conname,jsonb_build_object('parent',k.confrelid::regclass::text,'cols',(SELECT jsonb_agg(a.attname ORDER BY u.ordinality) FROM unnest(k.conkey) WITH ORDINALITY u(attnum,ordinality) JOIN pg_attribute a ON a.attrelid=k.conrelid AND a.attnum=u.attnum),'target',(SELECT jsonb_agg(a.attname ORDER BY u.ordinality) FROM unnest(k.confkey) WITH ORDINALITY u(attnum,ordinality) JOIN pg_attribute a ON a.attrelid=k.confrelid AND a.attnum=u.attnum))) FROM pg_constraint k WHERE k.conrelid=c.oid AND k.contype='f'),'{}'::jsonb)
))::text FROM pg_class c JOIN pg_namespace n ON n.oid=c.relnamespace WHERE n.nspname='public' AND c.relkind='r';
